// implementation of a rank-choice voting system using a hash table
class VotingSystem {
  private:
    std::vector<std::string> candidates;
    std::vector<std::vector<int>> votes;
    int numCandidates;
    int numVotes;

  public:
    VotingSystem(int numCandidates)
        : numCandidates(numCandidates), numVotes(0) {
    }
    void addVote(std::vector<int> vote) {
        votes.push_back(vote);
        numVotes++;
    }
    void printResults() {
        std::vector<int> candidateCounts(numCandidates + 1); // check this
        for (int i = 0; i < numVotes; i++) {
            for (int j = 0; j < numCandidates; j++) {
                candidateCounts[votes[i][j]]++;
            }
        }
        for (int i = 0; i < numCandidates; i++) {
            std::cout << "Candidate " << i << ": " << candidateCounts[i]
                      << " votes" << std::endl;
        }
    }
};
int main() {
    VotingSystem system(5);
    system.addVote({0, 1, 2, 3, 4});
    system.addVote({1, 2, 3, 4, 0});
    system.printResults();
    return 0;
}

