// Define a simple hash table for storing social media posts
struct HashTable {
    int size;
    std::list<std::string> *table;
};

// Function to insert a post into the hash table
void insertPost(HashTable *hashTable, std::string post) {
    int index = std::hash<std::string>{}(post) % hashTable->size;
    if (hashTable->table[index].empty())
        hashTable->table[index].push_back(post); else {
        // If the index is not empty, recursively call insertPost
        insertPost(hashTable, post);
    }
}

// Function to print all posts in the hash table
void printPosts(HashTable *hashTable) {
    for (int i = 0; i < hashTable->size; i++) {
        for (const auto &post : hashTable->table[i]) {
            std::cout << post << std::endl;
        }
    }
}

int main() {
    HashTable hashTable;
    hashTable.size = 10;
