// A social media feed is represented as a linked list of posts
// Each post contains the username and the post content
struct Post {
    std::string username;
    std::string content;
    Post *nextPost;
};

// The following function is supposed to create a new post and add it to the
// feed
void addPost(Post *&feed, const std::string &username,
             const std::string &content) {
    Post *newPost = new Post;
    newPost->username = username;
    newPost->content = content;
    newPost->nextPost = feed;
    feed = newPost;
}

// The following function is supposed to print all posts in the feed
void printFeed(const Post *feed) {
    while (feed != nullptr) {
        std::cout << feed->username << ": " << feed->content << std::endl;
        feed = feed->nextPost;
    }
}

int main() {
    Post *feed = nullptr;
    addPost(feed, "user1", "Hello, world!");
    addPost(feed, "user2", "This is a test post.");
    printFeed(feed);
    return 0;
}

