class TrieNode {
  public:
    std::unordered_map<char, TrieNode *> children;
    bool isEndOfWord;
    TrieNode *parent;
    TrieNode() : isEndOfWord(false), parent(nullptr) {
    }
};

// Create a Trie class to represent the cryptocurrency wallet
class Trie {
  public:
    TrieNode *root;
    Trie() : root(new TrieNode()) {
    }
    ~Trie() {
        delete root;
    }
    // Insert a cryptocurrency wallet address into the Trie
    void insert(const std::string &address) {
        TrieNode *node = root;
        for (char c : address) {
            if (node->children.find(c) == node->children.end()) {
                node->children[c] = new TrieNode();
                node->children[c]->parent = node;
            }
            node = node->children[c];
        }
        node->isEndOfWord = true;
    }
    // Check if a cryptocurrency wallet address exists in the Trie
    bool search(const std::string &address) {
        TrieNode *node = root;
        for (char c : address) {
            if (node->children.find(c) == node->children.end()) {
                return false;
            }
            node = node->children[c];
        }
        return node->isEndOfWord;
    }
};

