Node *compressList(Node *head) {
    Node *current = head;
    Node *previous = nullptr;
    while (current != nullptr) {
        if (current->data == 0) {
            if (previous != nullptr) {
                previous->next = current->next;
            } else {
                head = current->next;
            }
        } else {
            previous = current;
        }
