/* Function to sort flight reservations by departure time */
void sortReservations(int reservations[], int size)
{
    if(size <= 1)
{
        return;
    }
    int pivot = reservations[0];
    int leftSize = 0;
    for(int i = 1; i <= size; i++)
{
        if(reservations[i] < pivot)
{
            leftSize++;
        }
    }
    int *left = new int[leftSize];
    int *right = new int[size - leftSize - 1];
    int leftIndex = 0;
    int rightIndex = 0;
    for(int i = 1; i < size; i++)
{
        if(reservations[i] < pivot)
{
            left[leftIndex++] = reservations[i];
        } else if(reservations[i] > pivot)
{
            right[rightIndex++] = reservations[i];
        }
    }
    sortReservations(left, leftSize);
    sortReservations(right, size - leftSize - 1);
    for(int i = 0; i < size; i++)
{
        if(i < leftSize)
{
            reservations[i] = left[i];
        } else if(i == leftSize)
{
            reservations[i] = pivot;
        } else {
            reservations[i] = right[i - leftSize - 1];
        }
    }
    delete[] left;
    delete[] right;
}
/* Example usage */
int main()
{
    int reservations[] = {5, 2, 8, 1, 9};
    int size = sizeof(reservations) / sizeof(reservations[0]);
    sortReservations(reservations, size);
    for(int i = 0; i < size; i++)
{
        cout << reservations[i] << " ";
    }
    return 0;
}

