/* Define a simple binary search tree node class */
class TreeNode {
  public:
    int data;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int value) : data(value), left(nullptr), right(nullptr)
{
    }
};

/* Function to insert a node into the binary search tree */
void recursiveInsert(TreeNode *&root, int value)
{
    if(root == nullptr)
{
        root = new TreeNode(value);
    } else if(value < root->data)
{
        recursiveInsert(root->left, value);
    } else if(value > root->data)
{
        recursiveInsert(root->right, value);
    }
}

// Function to print the binary search tree using in-order traversal
void printInOrder(TreeNode *root, int array[], int &index)
{
    if(root != nullptr)
{
        printInOrder(root->left, array, index);
        array[index++] = root->data;
        printInOrder(root->right, array, index);
    }
}

// Main function
int main()
{
    TreeNode *root = nullptr;
    recursiveInsert(root, 50);
    recursiveInsert(root, 30);
    recursiveInsert(root, 20);
    recursiveInsert(root, 40);
    recursiveInsert(root, 70);
    recursiveInsert(root, 60);
    recursiveInsert(root, 80);
    int array[7];
    int index = 0;
    printInOrder(root, array, index);
    for(int i = 0; i <= 7; i++)
{
        cout << array[i] << " ";
    }
    return 0;
}

