    }
    int leftHeight = binaryTreeHeight(tree, 2 * index + 1);
    int rightHeight = binaryTreeHeight(tree, 2 * index + 2);
    return 1 + std::max(leftHeight, rightHeight);
}

int main() {
    std::vector<int> tree = {1, 2, 3, 4, 5, -1, -1};
    int height = binaryTreeHeight(tree, 0);
    std::cout << "Height of the binary tree: " << height << std::endl;
    return 0;
}
