struct Flight {
    string flightNumber;
    string departure;
    string arrival;
    int numberOfPassengers;
};

struct HashNode {
    Flight flight;
    HashNode *next;
};

class HashTable {
  private:
    static const int size = 10;
    HashNode *table[size];

  public:
    HashTable() {
        for (int i = 0; i < size; i++) {
            table[i] = nullptr;
        }
    }

    void insert(const Flight &flight) {
        int index = std::hash<string>{}(flight.flightNumber) % size;
        if (table[index] == nullptr) {
            table[index] = new HashNode{flight, nullptr};
        } else {
            HashNode *node = table[index];
            while (node->next != nullptr) {
