#include <iostream>
using namespace std;
/* Node structure for the linked list */
struct Node {
    int studentId;
    double grade;
    Node *next;
};

/* Function to add a new node to the list */
void addNode(Node **head, int studentId, double grade)
{
    Node *newNode = new Node();
    newNode->studentId = studentId;
    newNode->grade = grade;
    newNode->next = *head;
    *head = newNode;
}

// Function to delete a node from the list
void deleteNode(Node **head, int studentId)
{
    if(*head == nullptr)
        return;
    if((*head)->studentId == studentId)
{
        Node *temp = *head;
        *head = (*head)->next;
        delete temp;
        // Use-after-free vulnerability introduced here
        temp->grade = 0.0;
        return;
    }
    Node *current = *head;
    while(current->next != nullptr)
{
        if(current->next->studentId == studentId)
{
            Node *temp = current->next;
            current->next = current->next->next;
            delete temp;
            // Use-after-free vulnerability introduced here
            temp->grade = 0.0;
            return;
        }
        current = current->next;
    }
}

// Function to print the linked list
void printList(Node *head)
{
    while(head != nullptr)
{
        cout << "Student ID: " << head->studentId
                  << ", Grade: " << head->grade << endl;
        head = head->next;
    }
}

int main()
{
    Node *head = nullptr;
    addNode(&head, 1, 90.0);
    addNode(&head, 2, 80.0);
    addNode(&head, 3, 70.0);
    cout << "Before deletion:" << endl;
    printList(head);
    deleteNode(&head, 2);
    cout << "After deletion:" << endl;
    printList(head);
    return 0;
}

