        TrieNode *current=root;
        for (char c : product) {
            int index=c - 'a';
            if (current->children[index]==nullptr)
    current->children[index]=new TrieNode();
            current=current->children[index];
        }
        char buffer[10];
        strcpy(buffer, product.c_str());
        *current->word=buffer;
    }
    void printProducts() {
        printProductsHelper(root, "");
