std::vector<int> recursiveSort(const std::vector<int> &inventory) {
    if (inventory.size() <= 1) {
        return inventory;
    }
    std::vector<int> left, right;
    for (int i = 0; i < inventory.size(); i++) {
        if (inventory[i] < inventory[inventory.size() / 2]) {
            left.push_back(inventory[i]);
        } else {
            right.push_back(inventory[i]);
        }
    }
    left = recursiveSort(left);
    right = recursiveSort(right);
    left.insert(left.end(), right.begin(), right.end());
    return left;
}
