class Node {
  public:
    int data;
    Node *next;
    Node(int value) {
        data = value;
        next = nullptr;
    }
};
// BankingApplication class
class BankingApplication {
  private:
    Node *head;

  public:
    BankingApplication() {
        head = nullptr;
    }
    void addAccount(int accountNumber) {
        Node *newNode = new Node(accountNumber);
        if (head == nullptr) {
            head = newNode;
        } else {
            Node *temp = head;
            while (temp->next != nullptr) {
                temp = temp->next;
            }
            temp->next = newNode;
        }
    }
    void removeAccount(int accountNumber) {
        if (head == nullptr)
            return;
        if (head->data == accountNumber) {
            Node *temp = head;
            head = head->next;
            // BUG INTRODUCED HERE
            // No delete statement for temp
        } else {
            Node *temp = head;
            while (temp->next != nullptr) {
                if (temp->next->data == accountNumber) {
                    Node *nodeToRemove = temp->next;
                    temp->next = temp->next->next;
                    // No delete statement for nodeToRemove
                } else {
                    temp = temp->next;
                }
            }
        }
    }
    void printAccounts() {
        Node *temp = head;
        while (temp != nullptr) {
            std::cout << temp->data << " ";
            temp = temp->next;
        }
        std::cout << std::endl;
    }
};
// Example usage
