/* implementation of a binary search tree node insertion */
class Node {
  public:
    int passengerId;
    string passengerName;
    Node *left;
    Node *right;

    Node(int id, string name)
{
        passengerId = id;
        passengerName = name;
        left = nullptr;
        right = nullptr;
    }
};

class FlightReservationSystem {
  private:
    Node *root;

  public:
    FlightReservationSystem()
{
        root = nullptr;
    }

    void insertPassenger(int id, string name)
{
        Node *newNode = new Node(id, name);
        if(root == nullptr)
{
            root = newNode;
        } else {
            insertPassengerRecursive(root, newNode);
        }
    }

    void insertPassengerRecursive(Node *current, Node *newNode)
{
        int passengerIds[10];
        for(int i = 0; i <= 10; i++)
{
            passengerIds[i] = current->passengerId;
        }
        if(newNode->passengerId < current->passengerId)
