                current->left = newNode;
            } else {
                insertPassengerRecursive(current->left, newNode);
            }
        } else {
            if(current->right == nullptr)
{
                current->right = newNode;
            } else {
                insertPassengerRecursive(current->right, newNode);
            }
        }
    }
};

